pins={'research/ordinary13-residue-folds-model-draft/ResidueFoldFold87.lean.src': 'ff42c9123d06a684e30b5af953962d82b72ed33a814dcc72faa602f0f05f0161', 'research/ordinary13-residue-folds-model-draft/ResidueFoldFold87Residuals.lean.src': 'c52f3b3e7fec3186e6d9efa93ab6d5424c625359b105283d5bf5dc5c8d02c3b0', 'research/ordinary13-residue-folds-model-draft/ResidueFoldFold88.lean.src': '915f92db06125342a2a99757450a25c86b1b7c5049ad00bfa3afe3fc477d63c8', 'research/ordinary13-residue-folds-model-draft/ResidueFoldFold88Residuals.lean.src': 'ceca527ce4c67abc58fe8b9c3e82144807ee047c6c22d1701242df05a8a40be2', 'research/ordinary13-residue-folds-model-draft/ResidueFoldP88.lean.src': '96739da4451ffec0774ffe580d3a754561e194da647708ab3872d7cc143c0fea', 'research/ordinary13-residue-folds-model-draft/ResidueFoldP88Residuals.lean.src': '8db3637cc65a9bb7cdbacfdc127eb7e1cade5f1f7692009235c1dae3bb25fd62', 'research/ordinary13-residue-folds-model-draft/ResidueFoldP89.lean.src': '1cf3ece1241b09402110f78d7be1712b508e431c763772af5a0f6e91d3bb2a73', 'research/ordinary13-residue-folds-model-draft/ResidueFoldP89Residuals.lean.src': '02849926cb905aa822f0c077329ddef012c8058184ffd719a62c5350a24717c4', 'research/ordinary13-residue-folds-model-draft/ResidueFoldsModel.lean.src': '62f5b50c78596f6086ac6ae31f4a00679a3901c9826cf7e6debe6ff39da7db35', 'research/ordinary13-residue-folds-model-draft/generate.py': 'c6a6eed7e0d6b26ffd1c8cc5810921e0a975a4ab886b4b96aa118778a520cf2f', 'research/ordinary13-residue-folds-model-draft/generated.json': '46256cb22d308c1ff4db2094e3b27dd49788860ce334a897f0cd2e15b69c291d', 'research/ordinary13-residue-folds-model-draft/generate_bridges.py': '7510bb1bd53bfcf705f63c5fbb7b06df6e5ed89af1840016ac7f2021c4507329', 'research/ordinary13-residue-folds-model-draft/bridges-generated.json': 'ae61e6d2138908d65427fb29b36bb4ed9af3c5c5a0af83638b8ecf4d3e7346db', 'research/ordinary13-natural-residue-forced89-degree56/candidate.json': 'c18892fc5e50e091411cf24511481995ad2fdbab20e55068787722feca41a22a', 'research/ordinary13-natural-residue-forced89-degree56/check.py': '350537f8a3024121b139d3c4a6a9cc1b9c59d7ca080e30c58812e04b2f10f71c', 'research/ordinary13-natural-residue-forced89-degree56/receipt.json': 'beb633428beee90b6049162d9e77ae063755dcdf2c63a07283a97a2bcb12e123', 'research/ordinary13-natural-residue-eta-fold88-degree56/candidate.json': 'f71cb18bdc28088a7a7c7c7ae84afc15e49470ee3d4fa4076d8c25d6d2b89b58', 'research/ordinary13-natural-residue-eta-fold88-degree56/check.py': 'a918873ef259f3236d1519185c33921b5bec4792a7d53f270f6050e3e66428ee', 'research/ordinary13-natural-residue-eta-fold88-degree56/receipt.json': 'a9fc05755b636a5e3ba1d37973b4091998e3bae8346932b940b4deea29cbc2ca', 'research/ordinary13-natural-residue-forced88-degree60/candidate.json': 'cb488cb849c08c11d159f8805fdd7664c6472cbd41cefadc530e21060a5a1dd2', 'research/ordinary13-natural-residue-forced88-degree60/check.py': '8c5ef62f8908a2bbfc26b8232a1c936e49de1008302e7dfa332ffb18ef51ecef', 'research/ordinary13-natural-residue-forced88-degree60/receipt.json': '23979e4a28e0844ef4d1c8fd953b9f8f413b017a696cd69724c9b9fb60ebd8e4', 'research/ordinary13-natural-residue-eta-fold87-degree60/candidate.json': '81a09c0504bc786afb017483225e1fb6b1a52e9ddd98f53b0643dfb23c3a602f', 'research/ordinary13-natural-residue-eta-fold87-degree60/check.py': 'f08a934878e71aa733745f55e83f304e1677c59c2303e1f21d01b31c5b30e49c', 'research/ordinary13-natural-residue-eta-fold87-degree60/receipt.json': 'dd6c12c27c974ef90a626cf0f0280d81426b67150c919b01c4dfb9111656ff96', 'Lean/DiophantineConsistency/ModelDifferenceRing.lean': '5f8007e437fe309d0801bed075c03dc7ef5e7cba0138210aa1805e43a0869998', 'Lean/DiophantineConsistency/HAExpressionNoZeroEquiv.lean': 'd8f79bdea8b0f89235cfd3e19d3977b79fb6012bd0178c06ddbd104e1bb14f06'}
for f,h in pins.items():assert hashlib.sha256((D/f).read_bytes()).hexdigest()==h,f
for packet,check,receipt in [('ordinary13-residue-folds-model-draft','generate.py','generated.json'),('ordinary13-residue-folds-model-draft','generate_bridges.py','bridges-generated.json'),('ordinary13-natural-residue-eta-fold88-degree56','check.py','receipt.json'),('ordinary13-natural-residue-eta-fold87-degree60','check.py','receipt.json')]:
 p=D/'research'/packet
 assert subprocess.check_output([sys.executable,'-I','-S','-B',str(p/check)],cwd=D)==(p/receipt).read_bytes(),packet
src={x.name:x.read_text() for x in P.glob('*.lean.src')};assert len(src)==9
for n,s in src.items():assert not re.search(r'\b(?:sorry|admit|axiom|unsafe)\b',s),n
for tag in ['P89','Fold88','P88','Fold87']:
 r=src['ResidueFold'+tag+'Residuals.lean.src'];m=re.findall(r'^  !\[([^\n]+)\]$',r,re.M);assert ': Fin 4 → Expr (Fin 13)' in r and len(m)==1 and m[0].split(',')==['A0','A1','Fam','g72']
t=src['ResidueFoldsModel.lean.src']
for label in ['88_89','87_88']:
 assert all(f'theorem relation_{label}_{i}' in t for i in range(4))
 assert f'theorem native_equivalence_{label}' in t
assert t.count('hparent : PolynomialBridge')==4
def ev(g,v,p):
 env=dict(zip(g['witnesses'],v));env.update(zip(g['fixed_numerals'],p))
 for n,o,x,y in g['source']:
  a=x if type(x)==int else env[x];b=y if type(y)==int else env[y];env[n]={'+' : lambda:a+b,'-' : lambda:a-b,'*' : lambda:a*b}[o]()
 return [env[z] for z in ('A0','A1','Fam','g72','out')]
rng=random.Random(138887);cases=0
for ca,pa in [('ordinary13-natural-residue-eta-fold88-degree56','ordinary13-natural-residue-forced89-degree56'),('ordinary13-natural-residue-eta-fold87-degree60','ordinary13-natural-residue-forced88-degree60')]:
 a=json.loads((D/'research'/ca/'candidate.json').read_text());b=json.loads((D/'research'/pa/'candidate.json').read_text());assert a['witnesses']==b['witnesses'] and a['fixed_numerals']==b['fixed_numerals']
 for _ in range(120):
  v=[rng.randrange(-4,5) for _ in range(13)];p=[rng.randrange(-4,5) for _ in range(4)];assert ev(a,v,p)==ev(b,v,p);cases+=1
print(json.dumps({'scope':'bounded source and signed graph controls, no Lean','pinned_files':len(pins),'source_files':len(src),'finite_signed_graph_cases':cases,'separate_parent_bridges_explicit':True,'source_sha256':{n:hashlib.sha256(s.encode()).hexdigest() for n,s in sorted(src.items())}},sort_keys=True,indent=2))
